"""Topic-specific customer guides completing the supplied troubleshooting brief."""


def add_guides(page, section, pages):
    def s(title, text, checks=()):
        block = section(title, text, checks)
        block['ordered'] = bool(checks)
        return block

    def guide(slug, title, category, intro, sources, blocks, *, models=('L2', 'NOVA'), related=(), faq=(), illustration=None):
        item = page('troubleshooting/' + slug + '/', title, intro, 'Troubleshooting', blocks,
                    keywords='TOOCAA ' + slug.replace('-', ' ') + ', ' + title.lower(),
                    sources=sources, related=list(related) + ['support/ticket-checklist/'], faqs=faq)
        item.update(category=category, models=list(models), illustration=illustration)

    guide('uneven-cutting-depth', 'Uneven Laser Cutting Depth Across a Sheet', 'laser-cutting',
          'Find out whether uneven cuts follow the wood, the work surface, or a particular part of the machine before changing power.',
          ['l2Faq', 'novaCamera', 'settings'], [
        s('Map where the cut changes', 'Keep the first sample and mark which edge faced the front of the machine. A cut that succeeds in one corner but not another is different from a cut that fails at a glue pocket. Photograph both faces and note whether the sheet was bowed, supported unevenly, or thicker at the failed area.'),
        s('Check the sheet and support', 'Use a flat, identified offcut with a consistent thickness. A bow changes the distance from the head to the surface. Loose scraps underneath a panel can lift one corner even when the panel looks level from above.', ['Stop the job and let the material cool before removing it.', 'Measure the stock at several positions and remove loose debris from the bed.', 'Support the sheet using the working-panel arrangement specified for the machine.', 'Keep clamps and fixtures outside the planned head movement.']),
        s('Set focus for the actual surface', 'On L2, set the focusing rod against the workpiece and secure the module as described in the L2 FAQ. On NOVA, focus on the actual stock, then check the refreshed camera overlay. Camera calibration and laser focus solve different problems; moving artwork cannot correct a changing focal distance.'),
        s('Compare a small repeated pattern', 'When the machine and stock are safe, place the same simple test at separated positions on one flat offcut. Keep the file and settings unchanged. If the weak area moves with a rotated piece of wood, examine the stock. If it stays in the same bed position on multiple flat sheets, send the pattern and photographs to support. Do not attempt undocumented gantry or bed adjustments.'),
    ], related=['learn/materials/wood/', 'tutorials/focus-positioning/', 'troubleshooting/not-cutting-through/'],
          faq=[('Should I increase power only in the weak corner?', 'First rule out bowing, thickness changes and focus differences. A location-dependent fault on several flat sheets needs a machine inspection, not a hidden power correction in the artwork.')], illustration='cut-quality'),

    guide('kerf-too-wide', 'Laser Kerf Too Wide: Focus, Artwork & Fit', 'laser-cutting',
          'Check an unexpectedly wide cut and improve the fit of slots and tabs using measured samples rather than guessed lens changes.',
          ['l2Faq', 'settings', 'lightburnFiles'], [
        s('Separate the cut width from the drawn width', 'Kerf is material removed along a cut. A thick stroke displayed on screen is not necessarily a wide laser path, while an outlined stroke may import as two separate paths. Zoom into the file and use the processing preview to see whether the machine will trace one centerline or two boundaries.'),
        s('Inspect focus and duplicated passes', 'An out-of-focus mark or repeated exposure can leave a broader damaged edge. Check the file before compensating for the result.', ['Use a single, simple outline on known flat stock.', 'Remove duplicate vectors and confirm the intended number of passes.', 'Set focus for the actual surface using the model instructions.', 'Check power and speed units against the correct material reference.']),
        s('Measure the finished part', 'Let the sample cool, then measure an outside dimension, a hole, and a slot. Record the material batch and thickness along with the settings. Design dimensions and measured cut dimensions are different records. A fit allowance is valid only for the tested material and process; changing stock can change the fit.'),
        s('Apply a design allowance only after the test', 'Use the design software\'s documented offset or kerf-compensation control for a small fit coupon before nesting an entire sheet. Check both inside and outside features because the required adjustment acts in opposite directions. Do not fit an unapproved lens or repeatedly increase exposure to make a press-fit joint. Seek support if a sharply focused single line remains unusually wide.'),
    ], related=['tutorials/complex-designs/', 'use-cases/gift-box-packaging/', 'troubleshooting/uneven-cutting-depth/'],
          faq=[('Can one kerf allowance work for every sheet?', 'No. Keep a fit coupon for the actual stock, thickness, laser module and settings, and recheck it when any of those change.')]),

    guide('gradient-banding-photos', 'Bands or Stripes in Laser-Engraved Photos', 'engraving',
          'Distinguish scan-line gaps, image-processing artifacts and movement errors when a photo engraving shows visible bands.',
          ['lightburnImageMode', 'lightburnImages', 'lightburnInterval', 'studioFeatures'], [
        s('Look at the band direction', 'Photograph the engraving under even light and compare it with the image preview at finished size. Regular gaps parallel to the scan lines suggest a different issue from doubled edges or a repeated mechanical shift. If the bands are already visible in the source image, changing the machine will not restore the missing tones.'),
        s('Compare one small image region', 'Use a crop containing a smooth tone, a dark edge and a lighter area on the same material batch. Avoid reprocessing a whole portrait for every change.', ['Keep the crop size, material, focus and power/speed combination recorded.', 'Compare the original image and the exported image for posterization.', 'Check that the image layer uses the intended image or dithering mode.', 'Change only one image-processing or scan-spacing control for each sample.']),
        s('Compare Jarvis, Stucki and grayscale deliberately', 'In LightBurn, Jarvis and Stucki turn image tones into dot patterns. Its image-mode reference describes Jarvis as slower to process but better at retaining midtone shading, while Stucki processes faster. Grayscale instead varies laser power between the layer\'s minimum and maximum settings. Compare one mode at a time on the same small tonal crop and stock. Do not combine a mode change with new dimensions, line spacing and exposure, or assume these LightBurn controls have identical names in Studio.'),
        s('Check line interval in LightBurn', 'Line interval controls the distance between scan lines. Excessively close lines can overlap and lose detail; wide spacing can leave visible gaps. LightBurn provides an Interval Test for selecting spacing on the actual laser/material combination. Use that test and inspect the individual lines rather than assuming that the highest DPI gives the best photo.'),
        s('Keep image settings separate from motion faults', 'If vector lines are also wavy or displaced, investigate positioning and motion before adjusting the photograph. Save the test crop and the layer settings so the result can be reproduced. Do not compensate for slipping material or erratic movement with extra sharpening or exposure.'),
    ], related=['tutorials/photo-preparation/', 'troubleshooting/wavy-blurry-engraving/', 'tutorials/material-test/'],
          faq=[('Does a higher DPI always remove banding?', 'No. DPI and line interval affect scan density. Too much overlap can darken or blur the image; the useful interval must be tested on the real material.')]),

    guide('scorch-marks-engraving', 'Smoke Stains & Scorch Marks Around Engraving', 'engraving',
          'Identify surface smoke deposits, overexposure and airflow problems before changing an engraving design or adding masking.',
          ['novaFaq', 'novaInternalFilter', 'settings'], [
        s('Identify the mark before cleaning', 'Compare the area around the engraved shape with the engraved shape itself. A broad haze can be a smoke deposit, while a deeply darkened groove may indicate excessive exposure. Note whether the marks occur on every side, only behind the scan direction, or on the underside. Do not handle a hot or smoldering sample.'),
        s('Check the processing setup', 'NOVA\'s FAQ identifies processing parameters and air-pump operation as relevant checks for directional burn marks. Those are checks to separate, not reasons to increase power.', ['Inspect the artwork for duplicated paths or overlapping layers.', 'Confirm the intended engraving mode and speed units.', 'Check that accessible air tubing is not kinked and exhaust openings are clear.', 'Check the bed and scraps with power off, following the applicable cleaning guide.']),
        s('Test a small change', 'Use an offcut from the same batch and compare one controlled change at a time. Record whether the haze, engraving darkness or edge damage changed. A surface coating, finish or adhesive can alter the result even when the underlying board is the same species.'),
        s('Masking is not a ventilation repair', 'Only use masking whose complete composition is suitable for the documented process. Unknown tape or a stronger adhesive can introduce a new material hazard. Persistent smoke leakage, failed airflow, burning, or recurring alarms requires stopping the job and resolving the cause, not hiding the marks under tape.'),
    ], related=['troubleshooting/excessive-smoke-odor/', 'troubleshooting/burnt-charred-edges/', 'learn/materials/wood/'],
          faq=[('Should I add masking to every scorched engraving?', 'First check exposure, duplicate paths, focus and extraction. Masking cannot correct a ventilation fault, and its adhesive must itself be suitable for laser processing.')], illustration='cut-quality'),

    guide('motor-skipping-grinding', 'Laser Head Skipping, Grinding or Losing Position', 'hardware',
          'Stop a grinding or skipping movement, check visible obstructions, and distinguish an artwork-boundary problem from a motion fault.',
          ['manual', 'l2Safety', 'novaFaq'], [
        s('Stop the movement first', 'A head that chatters, stalls or moves in steps should not be left to finish the job. Stop using the normal machine controls. Let the machine stop completely and disconnect power before inspecting the working area. Do not reach into a moving gantry or attempt to hold the head in position.'),
        s('Look for a simple obstruction', 'Check the area you can inspect without disassembling the motion system.', ['Remove loose offcuts, raised workholding and objects in the travel path.', 'Check that the material and any rotary workpiece fit within the documented clearances.', 'Inspect visible cables or tubing for snagging without pulling connectors.', 'Look for displaced covers or a component loosened during a recent setup change.']),
        s('Check the file and coordinate setup', 'A design outside the device work area or an incorrect origin can send a frame movement toward a boundary. Confirm the selected machine profile and work area before another attempt. A file correction is appropriate only when the mechanics are unobstructed and the machine is otherwise ready.'),
        s('Do not tune the driver by guesswork', 'Motor-driver adjustment is a model-specific service operation, not a general user repair. Do not change motor current, hidden controller values, belt tension or limit-switch positions from a generic guide. A persistent noise or lost position after visible obstructions are removed needs support with the exact axis, movement direction, setup change and a safe recording of the original symptom.'),
    ], related=['troubleshooting/homing-failure/', 'troubleshooting/strange-noises-during-operation/', 'troubleshooting/frame-squareness-alignment/'],
          faq=[('Can I continue if the head moves again after skipping?', 'Lost position can misplace the remaining toolpath. Stop and address the cause before starting a new framed job; do not resume a damaged alignment by eye.')]),

    guide('strange-noises-during-operation', 'Unusual Noise from a TOOCAA Laser Machine', 'hardware',
          'Locate an unfamiliar rattle, scrape or fan noise without running an unsafe test or opening powered components.',
          ['manual', 'novaCoolingFan', 'l2Safety'], [
        s('Record when the noise happens', 'Note whether the sound begins at power-on, during homing, when the head changes direction, when air assist starts, or only while cutting. The timing helps distinguish motion, cooling and airflow sources. A new sound after installing an accessory deserves attention even if the first engraved mark looks normal.'),
        s('Inspect after stopping and powering down', 'Only inspect accessible areas covered by the user documentation. Keep the machine stopped if a component is loose or damaged.', ['Check the bed for scraps touching moving parts.', 'Inspect external exhaust tubing for contact that could transmit vibration.', 'Check workholding and accessories for a loose or shifted mounting.', 'Look for dirt around accessible fan openings without inserting tools into the fan.']),
        s('Distinguish a fan problem from a movement problem', 'A noise that changes with head direction is not the same as a fan rattle that occurs while stationary. NOVA has a specific cooling-fan cleaning guide; its procedure and access do not automatically apply to L2 or an external purifier. Identify the actual source before choosing a maintenance guide.'),
        s('When the machine should stay off', 'Stop for grinding, a stalled axis, a fan that does not run normally, an electrical smell, or a damaged guard. Do not repeatedly run the machine to collect a better recording. Tell support which operating stage produced the sound and what changed immediately beforehand. Do not open a power supply or lubricate an unidentified component to silence it.'),
    ], related=['troubleshooting/motor-skipping-grinding/', 'troubleshooting/overheating-warning/', 'support/maintenance/'],
          faq=[('Does every unusual noise mean the belts need tightening?', 'No. Scraps, workholding, ducts, fans and motion faults can sound different. Identify when and where it occurs before considering a documented adjustment.')]),

    guide('axis-drift-calibration', 'X/Y Position Drift Between Engraving Passes', 'hardware',
          'Track whether a shifted engraving comes from moving stock, changed coordinates, or a machine that is losing its position.',
          ['l2Faq', 'novaCamera', 'lightburnFiles'], [
        s('Keep the first and last positions', 'A design that shifts a little more with each pass is different from a constant camera-overlay offset. Mark the blank\'s orientation and retain the file. Do not move the material or drag the artwork to compensate before recording the original displacement.'),
        s('Check the reference that moved', 'Examine each reference independently.', ['Check whether the blank or fixture moved on the working panel.', 'Confirm that the file was not reimported at a different size or position.', 'Check origin and coordinate mode in the selected machine profile.', 'Check whether the problem started after a collision, accessory change or interrupted movement.']),
        s('Separate camera alignment from machine travel', 'On NOVA, an overlay that stays consistently offset calls for the official camera-calibration workflow. A toolpath that moves farther off with successive passes may involve stock movement or lost machine position. Recalibrating a camera cannot repair a slipping blank, an obstructed axis or a displaced origin.'),
        s('Use a small baseline, not repeated full jobs', 'When the machine is safe, compare a simple outline and a short filled sample on securely held offcut material. Stop if position is lost again. Send support the displacement direction, the file, machine profile and whether vectors and images are both affected. Do not flash firmware or edit motion calibration values merely to make a displaced sample line up.'),
    ], related=['troubleshooting/engraving-misalignment/', 'troubleshooting/nova-camera-positioning-offset/', 'troubleshooting/motor-skipping-grinding/'],
          faq=[('Can I fix a drifting job by moving the next layer?', 'That can hide the symptom while the references continue to move. Establish a stable workpiece, machine origin and toolpath before restarting the job.')]),

    guide('frame-squareness-alignment', 'A Cut Square Is Not Square: Geometry Checks', 'hardware',
          'Compare imported artwork, cut measurements and workpiece placement before attempting a machine-frame adjustment.',
          ['manual', 'l2Safety', 'lightburnFiles'], [
        s('Check the design dimensions first', 'Open a simple square in the design software and confirm equal side dimensions at the final physical size. A skewed photograph, image trace or imported drawing can look square without containing square geometry. Confirm the imported size instead of relying on how it fits the screen.'),
        s('Measure a simple cut sample', 'Use a small flat test piece only when the machine is safe and moving normally.', ['Check that the stock is fixed and does not rotate during processing.', 'Inspect the file for duplicate paths or a distorted import.', 'After cutting and cooling, measure both pairs of sides and both diagonals.', 'Record whether the error repeats in the same direction on another safe sample.']),
        s('Rule out measuring and material effects', 'Measure the same feature each time, rather than comparing one charred edge with another clean edge. Check for bowing, broken corners and loose assembly joints. If only an assembled box is skewed but the individual panels are square, inspect the tab allowance and assembly sequence before blaming the machine frame.'),
        s('Frame adjustment needs the correct procedure', 'Do not loosen the gantry, move limit switches or force rails into position using a general re-alignment suggestion. L2 assembly hardware and NOVA\'s enclosed structure are not the same service operation. Repeated unequal diagonals on sound simple samples should be sent to support with the original file, side and diagonal measurements, and any transport or collision history.'),
    ], related=['tutorials/complex-designs/', 'troubleshooting/axis-drift-calibration/', 'use-cases/gift-box-packaging/'],
          faq=[('Are unequal box diagonals proof that the laser frame is bent?', 'Not by themselves. Verify the drawing, individual cut panels, measurement points and assembly fit before requesting a frame inspection.')]),

    guide('nova-rotary-90-degree', 'NOVA 90-Degree Rotary Setup & Alignment', 'hardware',
          'Set up the NOVA rotary with the machine powered off, then check accessory detection, workpiece diameter and framing.',
          ['novaRotary', 'novaFaq'], [
        s('Use the NOVA rotary instructions', 'The NOVA rotary uses the machine\'s rotating X-axis arrangement. It is not the L2 5-in-1 rotary installation. Check the rotary identity, supported workpiece dimensions and installed laser module before starting. Workpiece length limits differ between the infrared and diode modules, so use the table in the linked NOVA rotary manual.'),
        s('Prepare the machine with power disconnected', 'Use the illustrated guide alongside the machine so the named panels and connection points can be identified correctly.', ['Stop, switch off, disconnect power and let the module cool.', 'Remove the blade cutting panel and aluminum protective plate using the orange handle, as illustrated.', 'Loosen the X-axis knob as directed, rotate the axis 90 degrees and secure the knob.', 'Install the rotary at the documented right-side connection point, secure it and connect the X-A cable to the expansion port.', 'Clear tools and obstructions and close the lid before reconnecting power.']),
        s('Check detection and the processing diameter', 'Connect NOVA in TOOCAA Studio and confirm that the accessory is detected. Enter the workpiece diameter at the area that will actually be engraved, not the widest part of a tapered cup. Check grip, balance and clearance over the full planned rotation before applying the design.'),
        s('Frame and focus before processing', 'The NOVA rotary guide distinguishes hard objects, which can use autofocus, from soft objects that need the documented manual height adjustment. Frame the design and make sure the processing area remains on the object, not the machine. If rotation is absent or irregular, stop and check the documented axis connections and diameter setting; do not substitute L2 rotation values.'),
    ], models=['NOVA'], related=['troubleshooting/rotary-attachment-issues/', 'troubleshooting/nova-autofocus-failed/', 'tutorials/irregular-shapes/'],
          faq=[('Can I follow the L2 rotary setup for NOVA?', 'No. NOVA uses a different accessory and a 90-degree X-axis setup. Follow the NOVA rotary manual and its module-specific size limits.')]),

    guide('toocaa-studio-connection', 'TOOCAA Studio Cannot Connect to NOVA', 'software',
          'Check the browser connection, serial-port permission, Wi-Fi subnet and device confirmation when NOVA will not connect to Studio.',
          ['novaConnection', 'novaFaq', 'studioFeatures'], [
        s('Identify the connection that failed', 'Record whether you selected USB or Wi-Fi and what appears in the connection dialog. A machine that has joined Wi-Fi is not necessarily connected to the current Studio session. The official NOVA tutorial recommends Google Chrome and asks you to select NOVA explicitly before choosing the connection method.'),
        s('For a USB connection', 'Save any open design before changing the session.', ['Connect a data-capable Type-C to Type-A cable as shown in the NOVA guide.', 'In Studio, choose Connect Device, select NOVA and choose the USB method.', 'Select the correct serial port in the browser permission dialog.', 'Close another machine-control session if it is holding the connection.', 'Keep a note of the exact permission or connection error if no usable port appears.']),
        s('For a Wi-Fi connection', 'The computer and NOVA must be on the same network and IP subnet. The current connection guide also requires TOOCAA Connect for the browser Wi-Fi workflow; install it only through the official guide or its Chrome Web Store link. On NOVA, inspect Settings > Wi-Fi and read the current address. In Studio, use Wi-Fi Connection > Connect New Device, enter that address and confirm on the touchscreen. A guest network with client isolation can prevent communication even when both devices have internet access.'),
        s('When it still cannot connect', 'The NOVA FAQ provides network-specific checks and a USB-assisted Wi-Fi setup. Use those before a reset. Keep firmware, browser and OS details together with the method tested. Do not open router ports, disable network security globally, or reset the machine during an active job just to make a connection dialog succeed.'),
    ], models=['NOVA'], related=['troubleshooting/wifi-connection-troubleshooting/', 'troubleshooting/usb-not-connecting/', 'troubleshooting/nova-firmware-ota/'],
          faq=[('NOVA has an IP address. Why is Studio still disconnected?', 'Check the computer\'s subnet, the current device address, and the confirmation prompt on NOVA. Wi-Fi association alone does not establish a Studio connection.')]),

    guide('file-transfer-failed', 'Laser Job File Transfer Failed', 'software',
          'Separate artwork import, job preparation and machine transfer errors without sending an incompatible machine file or changing firmware unnecessarily.',
          ['studioFeatures', 'novaOffline', 'l2Faq', 'lightburnFiles'], [
        s('Locate the stage that failed', 'Keep the original editable file and a copy of the export. A drawing that cannot be imported, a preview that cannot be generated, and a completed job that cannot be transferred are three different failures. Record the last successful stage and the exact message before converting the file again.'),
        s('Check import and preparation', 'Try a small known-good design rather than the complete customer batch.', ['Confirm that the format is supported by the actual software, not merely by another laser application.', 'Check imported dimensions, layers and missing fonts.', 'Reduce an overly complex file to a simple isolated object and generate its preview.', 'If the simple file works, reintroduce the artwork in manageable parts.']),
        s('Check the selected device and connection', 'Confirm the model shown in Studio and keep the supported connection stable during transfer. For Wi-Fi on NOVA, recheck the current IP address and device confirmation. For L2 USB, select its actual serial port. A prepared file for a different controller or work area is not a safe compatibility test.'),
        s('Do not assume every model accepts the same storage', 'NOVA\'s documented Offline Mode includes built-in example jobs; that does not prove that an arbitrary SD card or every exported file can be loaded there. Use the storage and machine-file procedure documented for the exact model and software. If a card error is displayed, retain the message and contact support before formatting a card that may contain the only copy of a job.'),
    ], related=['tutorials/laser-file-formats/', 'troubleshooting/toocaa-app-crashes/', 'troubleshooting/usb-not-connecting/'],
          faq=[('Can I rename a PNG to a machine-file extension?', 'No. Renaming an extension does not convert pixels into vectors or create machine instructions. Import and prepare the artwork in supported software.')]),

    guide('toocaa-app-crashes', 'TOOCAA Studio Freezes or Crashes During Preview', 'software',
          'Recover a browser-based Studio workflow, isolate complex artwork and preserve your project before clearing data or retrying a batch.',
          ['novaFaq', 'studioFeatures', 'novaConnection'], [
        s('Save the project before troubleshooting', 'Record whether Studio freezes during import, preview generation, connection, transfer or processing. If the browser responds, save a project copy and note the software/browser version. A frozen preview is not permission to assume a connected laser has stopped; use the machine\'s documented controls if a job is active.'),
        s('Reduce browser and artwork load', 'The NOVA FAQ describes preview freezes when several complex designs are placed on a single layer. Test a smaller working set instead of restarting the same overloaded job repeatedly.', ['Close unnecessary tabs and nonessential applications.', 'Open a copy containing one simple object and generate its preview.', 'Move separate designs to different colored layers using Studio\'s Move to command.', 'Hide unused layers with their visibility control and verify one design at a time.']),
        s('Check disk space and the connection separately', 'The same FAQ identifies insufficient system-drive space as a cause of camera-image and firmware-update failures. Check available space without deleting project files or browser data blindly. A successful preview with a failed transfer belongs to connection troubleshooting; a preview that fails while disconnected points toward the file or application environment.'),
        s('Build a reproducible support example', 'Keep the smallest project that reproduces the freeze and describe the stage at which it occurs. Include layer count, image dimensions, browser, OS and available memory if known. Do not repeatedly send a partially prepared job, erase all saved site data before backing up, or install an unofficial Studio build to work around the symptom.'),
    ], models=['NOVA', 'L2'], related=['tutorials/complex-designs/', 'troubleshooting/file-transfer-failed/', 'troubleshooting/nova-camera-preview-lag/'],
          faq=[('Why does a simple file work while a batch freezes?', 'A complex batch can require substantially more preview resources. Isolate designs and hide unused layers to identify whether the failure follows a particular object or the size of the combined job.')]),

    guide('nova-firmware-ota', 'NOVA Wi-Fi Firmware Update Troubleshooting', 'software',
          'Use NOVA\'s documented on-device update route, keep power stable and record the failure stage before choosing recovery.',
          ['novaFaq', 'novaConnection'], [
        s('Confirm that the update is for NOVA', 'Read the model and version shown on the device. The example version in a help article is not the version every customer should install. Finish or safely stop processing before an update, and keep a note of the current firmware and any reported error.'),
        s('Use the documented touchscreen update', 'The NOVA FAQ gives an on-device alternative when updating through Studio repeatedly fails.', ['Make sure NOVA is normally powered and connected to the intended Wi-Fi network.', 'From the touchscreen home screen, swipe down from the top to open the drop-down menu.', 'When an available-version notice is shown, select Check.', 'Review the offered update, select Update and leave the device undisturbed.', 'Allow the documented automatic restart to complete before reconnecting Studio.']),
        s('If an update through Studio fails', 'Check the computer\'s available system-drive space and the stability of the connection. The FAQ identifies storage pressure as one cause of failed firmware and camera-image updates. Do not interpret a failed browser update as evidence that the controller must be opened or reflashed using an unrelated utility.'),
        s('If progress stops or the machine will not return', 'Keep the exact screen message, version, connection method and elapsed stage. Follow the current official recovery instructions or contact support before interrupting an update that may still be writing. There is no generic power-cycle timing or emergency firmware file suitable for every failed update.'),
    ], models=['NOVA'], related=['troubleshooting/firmware-update-stuck/', 'troubleshooting/nova-touchscreen-issues/', 'troubleshooting/toocaa-studio-connection/'],
          faq=[('Should I install the version number pictured in the guide?', 'Use the version offered for your device and read its release information. The version displayed in an example screenshot is not a universal firmware target.')]),

    guide('nova-camera-positioning-offset', 'NOVA Camera Preview Does Not Match the Engraving', 'nova-smart',
          'Check lighting and workpiece focus, then use TOOCAA Studio\'s NOVA camera-calibration workflow to correct a persistent overlay offset.',
          ['novaCamera', 'novaLidCamera', 'novaFaq'], [
        s('Separate an overlay offset from a moving blank', 'Compare the preview with the actual workpiece without repositioning the material. A consistently displaced camera overlay differs from a blank that slips or a machine that loses position. Check focus for the real material thickness and refresh the overlay before deciding calibration is needed.'),
        s('Prepare the calibration sheet', 'The official workflow uses one clean, flat sheet of kraft paper from the NOVA material kit. Place it in the working area while the machine is powered off. Remove other objects and avoid direct sunlight or strong lighting that produces washed-out areas in the camera view. Keep the lid closed during the calibration process.'),
        s('Run the NOVA calibration in Studio', 'Connect the machine successfully and use the current on-screen wizard.', ['In the upper-left TOOCAA menu, open Laser Tools > Camera Calibration.', 'Continue to the framing stage and confirm that the framed area is fully covered by the paper.', 'Keep the lid closed while framing and autofocus complete.', 'Start the calibration-pattern engraving and do not move the paper.', 'Allow recognition and calibration to finish, then inspect a refreshed overlay.']),
        s('Check the result before the next finished piece', 'The official guide says NOVA adjusts the camera view for material thickness after autofocus. Routine thickness changes are not a reason to repeat calibration every time. Recheck after moving the machine, replacing camera-related parts or noticing a persistent offset. If the offset remains after correct calibration, send support a preview screenshot and a photo of the corresponding sample; do not loosen the camera mounting to compensate by eye.'),
    ], models=['NOVA'], related=['troubleshooting/engraving-misalignment/', 'troubleshooting/nova-camera-preview-lag/', 'tutorials/focus-positioning/'],
          faq=[('Must I calibrate again for every material thickness?', 'NOVA\'s camera guide describes thickness compensation after autofocus. Recalibrate for a persistent offset or a relevant machine/camera change, not automatically for every sheet.')]),

    guide('nova-autofocus-failed', 'NOVA Autofocus Fails or Reports No Material', 'nova-smart',
          'Distinguish a focusing-probe problem from material recognition and follow the NOVA focus-module checks before retrying.',
          ['novaFaq', 'novaFocus', 'novaLens', 'novaRotary'], [
        s('Read the exact focusing message', 'NOVA\'s FAQ connects a No material detected message after focusing with a probe that may be stuck or obstructed. That is not the same as the camera failing to identify a material recognition card. Record the message and whether the head moved, touched the workpiece, or stopped before reaching it.'),
        s('Check the stock and the focus area', 'Stop and disconnect power before access. Let the laser module cool. Check for a tilted blank, a loose surface layer or a fixture under the probe path. Do not repeatedly drive the head against an object to force detection.'),
        s('Inspect the Focus Module', 'Use the illustrated NOVA module instructions for the installed module.', ['Check for dust or residue around the magnetic Focus Module and probe.', 'Keep the probe from being pressed sideways, bent or used as a handle.', 'If removal is needed, support the module and follow the correct power-off removal sequence.', 'Reinstall the Focus Module fully and verify that no debris prevents it from seating.', 'Stop if the probe remains stuck, rusty or damaged rather than adding an unapproved lubricant.']),
        s('Use the focusing method appropriate to the workpiece', 'The NOVA rotary manual distinguishes autofocus for hard workpieces from the documented manual height method for soft ones. An irregular or compressible object may not behave like a flat rigid sheet. After correct reassembly, check focusing on suitable test stock; if the error returns, keep the machine stopped and send the exact symptom and module details to support.'),
    ], models=['NOVA'], related=['troubleshooting/nova-module-swap-not-recognized/', 'troubleshooting/nova-ai-material-recognition/', 'troubleshooting/nova-rotary-90-degree/'],
          faq=[('Does No material detected always mean the camera cannot recognize the material?', 'No. The NOVA FAQ identifies the focusing probe as a relevant cause when the message appears after focusing. Material-card recognition is a separate workflow.')]),

    guide('nova-touchscreen-issues', 'NOVA Touchscreen Unresponsive or Frozen', 'nova-smart',
          'Identify a frozen interface, keep an active job safe and follow the documented restart, reset and firmware checks.',
          ['novaFaq', 'novaOffline'], [
        s('Determine whether only the screen is affected', 'Note whether the screen is blank, frozen on one page, displaying an update, or responsive but ignoring a particular control. If processing is active, do not assume that a frozen picture means the laser has stopped. Use the documented machine stop procedure when it is necessary to make the work area safe.'),
        s('Preserve information before changing settings', 'Record the displayed page, firmware version if available, the last action and whether Studio is still connected. Keep a photo of an error screen instead of repeatedly tapping controls. An update-in-progress screen belongs to firmware recovery, not ordinary touchscreen troubleshooting.'),
        s('Use the FAQ recovery when the settings menu responds', 'For a malfunctioning or unresponsive display, the NOVA FAQ describes Restore Factory Settings followed by a restart and checking the firmware release. Use that menu route only when the machine is idle and the relevant controls can actually be reached. Record network and job settings first, let the restart fully finish, then reconnect and verify the configuration.'),
        s('When the controls cannot be reached', 'Do not invent a button-hold combination or attempt a firmware reflash through an unrelated device utility. A completely inaccessible screen, a repeating boot failure or visible physical damage should be reported to support with the exact startup sequence. After recovery, check a simple idle interaction and the normal connection before sending another processing job.'),
    ], models=['NOVA'], related=['troubleshooting/nova-smart-settings-reset/', 'troubleshooting/nova-firmware-ota/', 'troubleshooting/machine-wont-turn-on/'],
          faq=[('Can I use Restore Factory Settings while an update is running?', 'No. Use the firmware-update guidance for an update in progress. A general screen reset is not a documented way to interrupt firmware writing.')]),

    guide('nova-ai-material-recognition', 'NOVA Material Recognition Gives the Wrong Result', 'nova-smart',
          'Check the TOOCAA material recognition card, camera view and selected job instead of treating automatic settings as proof of material safety.',
          ['novaProduct', 'novaCamera', 'novaFaq', 'settings'], [
        s('Know what the recognition workflow reads', 'TOOCAA describes NOVA\'s automatic material settings as a camera workflow using material recognition cards or tags and the Studio material library. It is not a chemical analysis of any unknown sheet placed in the machine. Confirm the supplier\'s material identity even when a suggested preset appears.'),
        s('Check the view and the selected material', 'Before processing, compare the suggestion with the material you actually intend to use.', ['Check that the appropriate recognition card or tag is present and visible as directed by the product workflow.', 'Remove glare, overexposure and objects hiding camera reference points.', 'Confirm the selected laser module, operation and material thickness.', 'Refresh the camera view and compare the applied layer settings with the intended job.', 'Do not process a sheet whose composition or backing cannot be identified.']),
        s('Separate recognition from focus and calibration', 'A No material detected message after autofocus may concern the focus probe. A marker-point warning or a displaced overlay concerns the camera view and calibration. Use the corresponding guide rather than changing presets to suppress an unrelated message.'),
        s('Treat a preset as a starting reference', 'For documented stock, inspect power, speed units, passes and operation before a small controlled sample. If the card and material do not match, use the correct documented material workflow or ask support. Do not label unknown plastic as acrylic, or copy a setting for another module simply because the automatic suggestion is missing.'),
    ], models=['NOVA'], related=['troubleshooting/nova-autofocus-failed/', 'troubleshooting/nova-camera-positioning-offset/', 'learn/materials/'],
          faq=[('Does automatic recognition make an unknown plastic safe?', 'No. Identify the complete material and any coating or backing independently. A camera suggestion is not a safety assessment or approval to process PVC or an unknown composite.')]),

    guide('nova-smart-air-assist', 'NOVA Air Assist Has Weak or No Airflow', 'nova-smart',
          'Check air-pump operation, accessible tubing and job context when NOVA air assist is absent or not behaving as expected.',
          ['novaFaq', 'novaProduct', 'novaCoolingFan'], [
        s('Separate air assist from smoke extraction', 'Air assist supplies air near the processing area; the exhaust path removes smoke from the enclosure. A running exhaust fan does not prove that the air pump is delivering air, and a dirty exhaust filter is not the only possible cause of a directional burn mark.'),
        s('Record the behavior during the job', 'NOVA is described as having smart air assist. Its behavior can depend on the operation and job configuration, so note whether the problem appears during framing, engraving or cutting. Do not expect an idle machine to reproduce every airflow condition of a processing job.'),
        s('Inspect accessible tubing safely', 'Stop, switch off and disconnect power before handling air lines or reaching into the enclosure.', ['Look for a kinked, pinched or displaced accessible tube.', 'Check for visible debris at the accessible air outlet without inserting a sharp tool.', 'Confirm that a recent accessory or module change did not disturb a connection.', 'Use the module and accessory instructions for any removal or cleaning.', 'Keep liquids away from the air path and electrical parts.']),
        s('Do not keep cutting without resolving the fault', 'The NOVA FAQ specifically identifies pump operation and bent or clogged tubing as checks for burn marks. If air remains absent, the pump is noisy or hot, or cut quality changes sharply, stop and report the operation mode, settings, module and visible tube condition. Do not open the pump housing, bypass control electronics or use a higher power setting as compensation.'),
    ], models=['NOVA'], related=['troubleshooting/air-assist-pump-maintenance/', 'troubleshooting/scorch-marks-engraving/', 'troubleshooting/nova-dual-exhaust-weak/'],
          faq=[('Is the exhaust fan the air-assist pump?', 'No. They serve different parts of the airflow system. Identify which airflow is missing before choosing a maintenance or support procedure.')]),

    guide('nova-dual-exhaust-weak', 'NOVA Exhaust Airflow Is Weak or the Fan Stops', 'nova-smart',
          'Inspect the NOVA exhaust route and built-in filter, distinguish an optional purifier problem, and stop for unsafe smoke conditions.',
          ['novaInternalFilter', 'novaPurifierFilter', 'novaProduct'], [
        s('Stop for smoke escaping into the room', 'Do not continue a job with smoke leaking from the enclosure, a persistent unusual odor, a stopped fan or an active safety warning. A dual-channel design still needs a clear and correctly assembled exhaust route. Let the machine stop and cool before inspecting it.'),
        s('Inspect the complete route', 'Check the path in order rather than looking only at the visible fan.', ['With power disconnected, inspect accessible exhaust openings and tubing for blockage or a sharp bend.', 'Check the rear built-in filter housing for accumulated residue and correct seating.', 'If an optional purifier is fitted, inspect its own filter and airflow according to that accessory\'s instructions.', 'Keep the machine\'s laser-module cooling fan separate from these exhaust checks.']),
        s('Clean only the component that is meant to be cleaned', 'The NOVA built-in filter guide permits rinsing the removed built-in filter separately with clean water and requires complete drying before reinstallation. That permission does not extend to electrical parts, the machine interior, or every purifier cartridge. Do not wash an optional purifier filter unless its own instructions explicitly allow it.'),
        s('Verify before returning to processing', 'After correct reassembly, remove all tools and wipes, close the cover and check normal homing and exhaust operation using the manual. If airflow is still poor or a fan sounds abnormal, stop again and contact support. Include whether a purifier is fitted, which filter was serviced and whether the problem existed before maintenance.'),
    ], models=['NOVA'], related=['troubleshooting/nova-exhaust-filter-replacement/', 'troubleshooting/excessive-smoke-odor/', 'troubleshooting/overheating-warning/'],
          faq=[('Can I rinse every filter in the exhaust system?', 'No. NOVA\'s removed built-in machine filter has a documented rinsing procedure. An optional purifier cartridge has separate maintenance instructions and must not be treated as the same component.')]),

    guide('nova-breathing-light-status', 'NOVA Status Light Shows an Unexpected Pattern', 'nova-smart',
          'Record the light pattern together with the touchscreen message and operating stage rather than applying another machine\'s color codes.',
          ['novaDescription', 'novaFaq', 'l2Lights'], [
        s('Use the screen and the light together', 'A light is a status cue, not a complete diagnosis. Record its color, whether it is steady, breathing or flashing, and the exact touchscreen message. Note whether NOVA is starting, framing, focusing, processing, paused or updating. That context is more useful than reporting only that the light is red.'),
        s('Do not use an L2 light chart for NOVA', 'The L2 indicator-light document describes L2 states. It does not establish NOVA meanings, and an informal green-ready / red-error chart should not be substituted for a model-specific reference. Use the current NOVA information and the actual on-screen warning before choosing a remedy.'),
        s('Respond to the underlying condition', 'Start with the condition shown by the device.', ['For a cover or module warning, stop and check normal installation without defeating a safeguard.', 'For a focus or camera message, keep the exact wording and use the relevant NOVA guide.', 'For an update notice, let the documented update process complete before a normal restart.', 'For smoke, overheating or unexpected movement, stop processing and address the hazard first.']),
        s('Send a useful status record', 'If the pattern remains unexplained, provide support with a short recording taken without recreating a hazardous job, the screen message, installed module and firmware version. Do not try to force a preferred color by disabling sensors, changing hidden settings or repeatedly starting a failed job.'),
    ], models=['NOVA'], related=['troubleshooting/safety-alarm/', 'troubleshooting/nova-autofocus-failed/', 'troubleshooting/nova-touchscreen-issues/'],
          faq=[('Can I use the L2 beep and light table to diagnose NOVA?', 'No. A reference for L2 is not a NOVA status decoder. Keep the NOVA screen message and the operating stage together with the observed light pattern.')]),

    guide('nova-child-lock-forgot-password', 'NOVA Safety Lock or Forgotten Access Code', 'nova-smart',
          'Identify the actual lock message, distinguish account access from machine safeguards, and get authorized help without bypassing protection.',
          ['novaDescription', 'novaFaq', 'contact'], [
        s('Identify what is asking for access', 'Take a clear photo of the prompt and note whether it appears on NOVA\'s touchscreen, in Studio, or on a store/account sign-in page. A cover interlock, an undetected module, a software account and a PIN prompt are not the same lock. Do not assume that every refusal to start is a forgotten password.'),
        s('Check normal readiness first', 'The NOVA FAQ lists lid closure, module installation and bottom-cover alignment as checks for startup or initialization failure. Check those items with the machine stopped and power disconnected where access is required. Do not bridge a sensor, insert a substitute key, or change wiring to make the machine ready.'),
        s('For an actual forgotten code', 'The NOVA FAQ linked here does not publish a universal master PIN or a child-lock bypass sequence. Contact TOOCAA through its official private channel with the exact prompt, machine serial/order details and proof of ownership if requested. Do not post serial numbers, account credentials or private order information in a public forum.'),
        s('Do not use a reset as an undocumented bypass', 'A factory reset is described for certain touchscreen and connection problems; that does not prove it removes every access restriction. Ask support whether a reset is appropriate for the specific prompt before using it. After authorized recovery, restore normal safeguards and keep access limited to trained users. Laser processing still requires attendance and an appropriate workspace.'),
    ], models=['NOVA'], related=['troubleshooting/nova-smart-settings-reset/', 'troubleshooting/protective-cover-sensor/', 'support/contact/'],
          faq=[('Is there a public master unlock code for NOVA?', 'The reviewed NOVA FAQ does not provide one. Use official support for an actual access-code problem; do not follow a sensor bypass or an unverified master-code claim.')]),

    guide('nova-module-swap-not-recognized', 'NOVA Does Not Recognize the Laser Module', 'nova-smart',
          'Check compatibility, seating, fasteners and normal startup after a NOVA module change without forcing the connector or bypassing detection.',
          ['novaLens', 'novaFaq', 'novaProduct'], [
        s('Confirm the module and the symptom', 'Record the installed module identity and whether NOVA reports no module, fails initialization or shows a different warning. A compatible product name is not enough if the part, mount or firmware requirement differs. Do not apply the 10W/20W window-maintenance procedure to an infrared module without its own matching instructions.'),
        s('Power off before checking the mounting', 'The NOVA 10W/20W maintenance guide describes supporting the cooled module, removing its two securing screws and sliding it horizontally. Use its illustrations for the actual locating features.', ['Stop, switch off, disconnect power and allow cooling.', 'Check that the correct module is fitted and its mounting area is free of debris.', 'If reseating is needed, follow the illustrated removal/reinstallation sequence and support the module.', 'Stop if the module resists sliding into position; withdraw and realign rather than forcing it.', 'Secure the module and check that the Focus Module is fully seated before power is restored.']),
        s('Check the protective parts too', 'The NOVA FAQ identifies the lid and bottom cover as part of normal initialization checks. Reinstall protective parts correctly after maintenance and clear all tools from the enclosure. Do not run the machine with a loose module or an open connector simply to see whether detection changes.'),
        s('If detection still fails', 'Keep the machine stopped and send support the old/new module identities, error screen and the setup change that preceded it. Do not scrape contact pins, bend connectors, install unrelated firmware or override module detection. A damaged mount or electrical contact needs the correct service response rather than another forced insertion.'),
    ], models=['NOVA'], related=['troubleshooting/nova-module-removal-install/', 'troubleshooting/nova-autofocus-failed/', 'troubleshooting/firmware-update-stuck/'],
          faq=[('Should I push harder if the module will not seat?', 'No. The official guide says to stop and realign when resistance is significant. Forcing the mount can damage locating features or connectors.')]),

    guide('nova-camera-preview-lag', 'NOVA Camera Preview Is Slow or Frozen', 'nova-smart',
          'Distinguish a stale camera image from a connection failure or an overloaded Studio preview, then check the smallest reproducible case.',
          ['novaFaq', 'novaCamera', 'novaConnection', 'novaLidCamera'], [
        s('Compare the live view and the design preview', 'A camera frame that does not refresh is different from a design preview that takes too long to generate. Note whether Studio remains connected, the device screen responds and the software can refresh an empty-work-area image. Do not move the blank and start engraving against an old overlay.'),
        s('Reduce the application load', 'The NOVA FAQ discusses limited system-drive space affecting camera-image loading and complex multi-design previews exhausting browser resources.', ['Save the design before closing tabs or restarting the browser.', 'Close unnecessary tabs and applications and check available system-drive space.', 'Test a simple project with one visible design layer.', 'Hide other complex layers and refresh the overlay before positioning.']),
        s('Check the connection without changing several things at once', 'For USB, check the data cable, selected port and competing control sessions. For Wi-Fi, confirm the current address, shared subnet and device confirmation. Compare a supported alternate connection only after saving the project and following the normal reconnect procedure. Do not assume a frozen picture is proof of a defective camera.'),
        s('Keep blur and latency separate', 'A refreshed image with fixed spots or blur may need the official top-cover camera cleaning procedure, followed by calibration. Cleaning a lens will not resolve an overloaded preview computation. If lag persists with a simple project, report browser/OS versions, connection method, available disk space and whether the camera image or design preview is affected.'),
    ], models=['NOVA'], related=['troubleshooting/toocaa-app-crashes/', 'troubleshooting/toocaa-studio-connection/', 'troubleshooting/nova-camera-positioning-offset/'],
          faq=[('Can I engrave using the last camera picture if refresh fails?', 'Do not rely on a stale overlay after the workpiece or machine state changes. Restore a current preview and verify placement before processing.')]),

    guide('nova-smart-settings-reset', 'Restore NOVA Factory Settings Safely', 'nova-smart',
          'Use the documented reset for the right symptom, record your configuration and verify reconnection before returning to a job.',
          ['novaFaq', 'novaCamera', 'novaConnection'], [
        s('Know why you are resetting', 'The NOVA FAQ describes Restore Factory Settings for certain display or Wi-Fi problems and says a full restart is required afterward. A reset is not a general repair for blocked airflow, a damaged focus probe, misinstalled hardware or an interrupted update. Diagnose that category first.'),
        s('Record what you will need again', 'Before resetting an idle, responsive machine, save the editable project and record the machine identity, firmware version, network details and job configuration. Keep screenshots of relevant settings. A screenshot record is not a promise that there is an automatic export-and-restore feature for every calibration or preference.'),
        s('Follow the normal settings-menu route', 'Use Restore Factory Settings in the machine\'s settings menu as described by the FAQ. Allow the device to restart fully before deciding that the reset failed. If the screen cannot reach that menu, ask support for the specific recovery procedure rather than inventing a button combination.'),
        s('Recheck the working setup', 'After the restart, reconnect using the documented NOVA workflow. Confirm the selected device, Wi-Fi information where needed, installed module, focus behavior and current overlay. Recalibrate the camera if alignment is visibly wrong, then use a small suitable test. Do not immediately rerun a saved customer job with unverified settings or repeat resets indefinitely when a fault returns.'),
    ], models=['NOVA'], related=['troubleshooting/nova-touchscreen-issues/', 'troubleshooting/wifi-connection-troubleshooting/', 'troubleshooting/nova-camera-positioning-offset/'],
          faq=[('Will a reset fix every NOVA warning?', 'No. It does not replace hardware installation checks, cleaning or a correct firmware-recovery procedure. Use it for the symptom covered by the official guidance and verify the setup afterward.')]),

    guide('flame-detection-false-alarm', 'Flame Detection Alarm: Checks Before Restarting', 'safety',
          'Treat a flame warning as a safety event, inspect only after the area is safe, and do not disable detection to finish a job.',
          ['l2Alarm', 'l2Safety', 'novaDescription'], [
        s('Do not assume the warning is false', 'A brief flame, hot residue or a small fire may no longer be visible when you reach the machine. Stop processing using the documented controls and follow the machine\'s fire-safety procedure. Keep people clear and do not restart to prove that the alarm was unnecessary.'),
        s('Identify the machine and warning', 'The L2 alarm reference lists one long beep followed by four short beeps for flame detected in the working area. That is an L2 reference, not a NOVA sound-code table. For NOVA, preserve the actual touchscreen message and the operating stage. Do not silence the warning before recording what triggered it.'),
        s('Inspect only after the work area is safe and cool', 'Disconnect power before maintenance or reaching into the machine.', ['Check for charred scraps, deposits or damage around the bed and workpiece.', 'Verify the material identity, coating and backing instead of relying on its appearance.', 'Review duplicate paths, repeated passes and the selected cutting/engraving mode.', 'Check the accessible air and exhaust routes for blockage using their maintenance instructions.']),
        s('Recurring alarms need a cause, not a bypass', 'If the alarm repeats without an understood and corrected cause, leave the machine out of processing service and contact support. Provide the original file, stock details, settings and warning record. Do not cover a detector, change unapproved sensitivity values or run unattended. An alarm disappearing after a restart does not establish that the material or setup is safe.'),
    ], related=['troubleshooting/excessive-smoke-odor/', 'troubleshooting/overheating-warning/', 'tutorials/laser-safety/'],
          faq=[('Can I turn off flame detection if I see no flame?', 'No. A visual check does not prove the event was false. Resolve the condition or get model-specific support without defeating detection.')]),

    guide('protective-cover-sensor', 'Protective Cover or Guard Warning on TOOCAA', 'safety',
          'Check normal lid and guard installation, identify a recurring interlock warning, and keep safeguards intact during diagnosis.',
          ['l2Alarm', 'l2Safety', 'novaFaq'], [
        s('Read the warning before moving parts', 'Record whether the warning appears during startup, framing or processing. L2\'s alarm reference identifies two short beeps with opening the shield during laser processing. NOVA\'s FAQ includes lid closure, module installation and bottom-cover alignment in initialization checks. These are different model contexts, not one interchangeable sensor procedure.'),
        s('Check ordinary closure', 'Stop the machine before inspecting the enclosure.', ['Remove stock, cables or fixtures that physically prevent the lid or protective part from seating normally.', 'Check for visible damage, loose hinges or displaced panels without disassembling the sensor.', 'If an accessory required a panel to be removed, reinstall the protective arrangement specified by that accessory\'s manual.', 'Do not push harder against a lid that is obstructed or distorted.']),
        s('Keep magnets and wiring out of the test', 'Do not tape a switch shut, add a magnet to simulate closure, bridge a connector or operate with a protective part removed. Those actions can make an unsafe machine appear ready while leaving the underlying fault unresolved. A damaged or unreliable enclosure should remain out of use until repaired.'),
        s('When normal closure still gives a warning', 'Send support a photograph showing the actual cover position, the model, accessory setup and full message. Mention whether the issue began after transport, cleaning or an accessory installation. Do not repeat laser-output tests with an unresolved interlock. The useful result is reliable operation with all guards normally installed, not merely clearing the warning once.'),
    ], related=['troubleshooting/nova-module-swap-not-recognized/', 'troubleshooting/nova-child-lock-forgot-password/', 'tutorials/laser-safety/'],
          faq=[('Can I use an external magnet to check a cover sensor?', 'Do not use a sensor bypass to make the machine operate. Check normal closure and ask support for the exact diagnostic procedure if the warning remains.')]),

    guide('emergency-stop-reset', 'After an Emergency Stop: Before You Restart', 'safety',
          'Make the work area safe, identify why the job stopped and recheck placement before starting a new job after an urgent stop.',
          ['l2Safety', 'novaOffline', 'l2Alarm'], [
        s('Resolve the reason for stopping', 'An emergency stop is a response to a condition, not a nuisance to clear. Keep the machine stopped while smoke, heat, unexpected movement, damaged parts or an unsafe workpiece remain. Follow the exact machine controls and safety instructions; different models do not necessarily have the same button or reset mechanism.'),
        s('Inspect with the right power state', 'For access or maintenance, disconnect power and let parts cool as directed by the manual.', ['Remove the cause of an obstruction only when the machine is stopped.', 'Inspect the stock and fixtures for movement, heat damage or a partially cut section.', 'Check that all protective parts are correctly installed.', 'Record any alarm, error screen and the stage where processing stopped.']),
        s('Distinguish Pause from Stop', 'NOVA\'s Offline Mode guide distinguishes pausing/resuming from Stop: Stop ends that job and returns to the home screen. Do not assume that releasing a control or reconnecting Studio restores the original coordinate state or resumes at the correct point. Use the model\'s documented continuation behavior.'),
        s('Prepare a new controlled start', 'Confirm machine identity, origin, workpiece placement, focus and all job settings before another framed start. A partially processed piece can react differently to a repeated full job. If there was a collision, lost position, persistent heat or a recurring warning, request support instead of restarting on the same customer part. Never use an undocumented button sequence to override an unresolved stop condition.'),
    ], related=['troubleshooting/safety-alarm/', 'troubleshooting/axis-drift-calibration/', 'support/ticket-checklist/'],
          faq=[('Does Stop behave exactly like Pause?', 'No. NOVA\'s offline guide says Stop ends the current job. Check the documented behavior for the actual model before expecting processing to continue.')]),

    guide('overheating-warning', 'Laser Overheating Warning or Cooling Problem', 'safety',
          'Stop for a temperature warning, check the relevant cooling and exhaust paths and avoid an unsupported timed restart.',
          ['l2Safety', 'l2Faq', 'novaCoolingFan', 'novaInternalFilter'], [
        s('Stop and preserve the warning', 'Record the exact temperature or cooling message, processing settings and stage of the job. A hot laser module, an exhaust problem and a hot external purifier involve different components. Do not assume that a warning clearing briefly means the machine is ready to continue a long cut.'),
        s('Check the environment and ventilation', 'L2\'s safety guide specifies its permitted operating environment; use that model reference rather than assuming the same limits for every product. Keep cooling and exhaust openings unobstructed. Do not place the machine among scraps or loose coverings that interfere with air movement.'),
        s('Inspect after shutdown and cooling', 'Disconnect power and let the laser module cool completely before cleaning.', ['Inspect accessible cooling-fan areas for dust, residue or damage.', 'Keep module cooling separate from the enclosure exhaust and any optional purifier.', 'Follow the exact component cleaning guide and use compatible tools.', 'Do not insert tools into a fan, wash electrical parts or apply liquid directly to the module.']),
        s('Resume only after normal cooling is established', 'The NOVA fan guide calls for stopping when the fan remains abnormal, noisy or unable to cool properly after cleaning. Do not invent a fixed waiting time or disable a temperature sensor. A recurring warning, a fan that does not run normally, unusual odor or damaged wiring needs support before processing resumes. Report which component appears affected and whether the warning returns on a small normal test.'),
    ], related=['troubleshooting/strange-noises-during-operation/', 'troubleshooting/nova-dual-exhaust-weak/', 'troubleshooting/laser-module-lifespan/'],
          faq=[('Can I restart after waiting a fixed number of minutes?', 'There is no universal cooldown time for an unresolved fault. Allow cooling and verify the cause and normal operation using the model-specific instructions.')]),

    guide('nova-exhaust-filter-replacement', 'Clean or Replace the NOVA Built-in Machine Filter', 'safety',
          'Remove and clean the NOVA rear filter outside the machine, dry it completely, and replace damaged or persistently blocked stock.',
          ['novaInternalFilter', 'novaPurifierFilter'], [
        s('Identify the built-in filter', 'This guide concerns the filter held in the removable white grille housing at the rear of NOVA. An optional external purifier filter is a separate component. A maintenance reminder or visible residue calls for inspection; cleaning the built-in filter does not automatically mean that every filter in the system should be washed.'),
        s('Prepare and remove it safely', 'Stop processing, switch off, disconnect power and allow the laser module to cool. Use the illustrated filter guide to identify the housing.', ['With power disconnected, hold the gantry at both sides and move it toward the front as illustrated, stopping if it resists.', 'Wipe the specified rear interior surfaces using compatible, lightly moistened wipes without dripping liquid into openings.', 'Lift the rear filter housing straight upward without prying or forceful twisting.', 'Remove the filter from its housing and take it outside the machine for cleaning.']),
        s('Wash the removed filter, then dry it throughout', 'The official procedure permits gently rinsing this removed built-in filter with clean water. Do not rinse the machine or electrical parts, and do not wring the filter. Blot surface water, then let it air-dry completely in a clean ventilated place. Surface dryness alone is insufficient. Dry the housing separately and remove loose paper fibers.'),
        s('Reinstall and inspect the airflow', 'Fit the fully dry filter flat, without folds or curled edges, and seat the housing correctly. Remove all wipes and tools before restoring power. A torn, deformed or still severely clogged filter needs a compatible replacement. Verify normal operation and airflow; reset this maintenance timer only after cleaning, drying and reinstallation are actually complete.'),
    ], models=['NOVA'], related=['troubleshooting/nova-dual-exhaust-weak/', 'troubleshooting/excessive-smoke-odor/', 'support/maintenance/'],
          faq=[('Can I reinstall the filter after blotting it with a towel?', 'Not until it is completely dry throughout. The official instructions require air-drying fully and checking the housing and cleaned areas before power is restored.')], illustration='nova-filter'),

    guide('lens-mirror-cleaning', 'Laser Module Window Cleaning: NOVA & L2', 'maintenance',
          'Inspect deposits and damage on the correct optical window, use dedicated cleaning materials and follow the module-specific removal procedure.',
          ['novaLens', 'l2Faq', 'l2Safety'], [
        s('Identify the component, not just the word lens', 'These enclosed desktop lasers do not share a generic CO2 mirror-adjustment procedure. Identify the machine and installed module before accessing optics. NOVA\'s illustrated window guide applies specifically to its 10W and 20W modules; the infrared module and L2 need their own matching instructions.'),
        s('Prepare clean tools and a cold, disconnected module', 'Stop, switch off, unplug and allow cooling. Keep a clean exterior cloth separate from dedicated lens tissue or a lens-cleaning cloth. Use an optical cleaner compatible with the window coating only when wet cleaning is needed. Do not spray into the module or reuse a dirty wipe from the outer housing on the optical surface.'),
        s('For a NOVA 10W or 20W window', 'Follow the current illustrations while supporting the module.', ['Remove the two securing screws, support the module and slide it out horizontally as shown.', 'Clean the exterior first, then lift the Focus Module straight up by its body, not the probe.', 'Remove loose dust and gently clean the window with fresh lens-cleaning material.', 'Inspect the dry surface for remaining deposits, scratches, cracks or burn marks.', 'Reinstall the Focus Module, seat the laser module correctly and tighten both securing screws before restoring power.']),
        s('Replace a damaged window instead of rubbing harder', 'The NOVA guide distinguishes removable contamination from damage or marks that remain after cleaning. A replacement must match the installed module. Do not scrape the surface or overtighten its threaded metal ring. For L2, use the manufacturer\'s linked module/lens instructions rather than copying NOVA removal steps. After correct reassembly, verify a small suitable sample and stop if focusing or output remains abnormal.'),
    ], related=['troubleshooting/weak-laser-output/', 'troubleshooting/nova-module-removal-install/', 'troubleshooting/laser-module-lifespan/'],
          faq=[('Does every dirty window need replacement?', 'No. Inspect after gentle cleaning and complete drying. Replace a damaged window or one with contamination that cannot be removed, using the specification for that module.')], illustration='nova-window'),

    guide('belt-tension-adjustment', 'Check a Loose Belt Before Adjusting Tension', 'maintenance',
          'Distinguish a visibly loose or damaged belt from a file or workholding error and obtain the correct adjustment procedure for the machine.',
          ['novaRod', 'manual', 'l2Safety'], [
        s('Confirm that the belt is involved', 'Misaligned artwork does not by itself prove incorrect belt tension. Check whether a blank moved, an origin changed or the head hit an obstruction. A damaged belt, visible slack or repeatable lost motion is more specific evidence. Keep the machine stopped for grinding or skipped movement.'),
        s('Inspect only with power disconnected', 'Follow the model\'s access instructions and do not pull on cables or force an axis.', ['Look for damaged teeth, fraying, a displaced belt or an obvious obstruction.', 'Check whether a recent accessory or assembly change preceded the problem.', 'On NOVA, use the slide-rod maintenance guidance for the permitted movement and belt inspection.', 'Record the affected axis and photograph visible damage without dismantling the drive.']),
        s('Use the model-specific adjustment', 'NOVA\'s rod-maintenance guide says to follow the corresponding adjustment instructions when a belt is loose. It does not specify a universal screw-turn count, force or belt frequency. Do not tighten until the belt feels like a string, move a pulley to compensate for a skewed frame, or apply an unrelated printer/CNC tension rule. Obtain the correct procedure for the exact hardware revision from TOOCAA when it is not available with the machine.'),
        s('Check the result with a small geometry test', 'After a documented adjustment and full reassembly, confirm normal homing and frame movement. Compare a simple small outline with the retained baseline. Continued skipping, unequal geometry or unusual noise means the cause is not resolved. Do not add more tension repeatedly to conceal another mechanical fault.'),
    ], related=['troubleshooting/motor-skipping-grinding/', 'troubleshooting/axis-drift-calibration/', 'troubleshooting/frame-squareness-alignment/'],
          faq=[('Is there one correct number of turns for every TOOCAA belt?', 'No. Hardware and adjustment points differ. Use the exact model procedure rather than an arbitrary screw-turn count or tension-by-feel rule.')]),

    guide('rail-lubrication-guide', 'Slide-Rod Cleaning & Lubrication', 'maintenance',
          'Remove residue from the correct motion surfaces and use only the lubricant and access method approved for the installed machine.',
          ['novaRod', 'l2Safety', 'manual'], [
        s('Identify the motion surface first', 'NOVA\'s documentation calls these slide rods. Do not assume that every shiny shaft, belt, wheel, bearing or enclosure surface should be greased. Identify the machine and the maintenance item before choosing a product. A generic spray recommendation is not a substitute for an approved lubricant.'),
        s('Clean and distribute the specified grease on NOVA', 'The NOVA slide-rod guide describes the following maintenance sequence, with power disconnected and the module cool.', ['Remove dust, tar and old lubricant from the slide rods using compatible cleaning materials.', 'Apply the lubricating grease specified for the component.', 'Move the axis evenly as allowed by the guide to distribute the grease; stop for resistance.', 'Wipe away excess rather than leaving a heavy layer to collect debris.', 'Inspect smooth movement and belt condition before reassembly and normal operation.']),
        s('Do not invent a replacement product or schedule', 'The linked guide does not name a universal retail grease or a fixed service interval for every work environment. Use the supplied or specifically approved product, and ask TOOCAA if its specification is unclear. Keep lubricant away from optics, belts, electrical contacts and the working stock. Do not use a general-purpose solvent spray as an assumed substitute.'),
        s('Keep a simple maintenance record', 'Record the date, product specification and observed condition. Recheck when a reminder appears or residue and uneven movement return. L2 users should follow L2\'s corresponding maintenance instructions rather than transferring the NOVA access procedure. Persistent rough travel or a recurring mechanical noise belongs with support, not another unverified coating of grease.'),
    ], related=['troubleshooting/strange-noises-during-operation/', 'troubleshooting/belt-tension-adjustment/', 'support/maintenance/'],
          faq=[('Can I use any household lubricating spray?', 'No. Use a lubricant explicitly approved for the particular motion component and keep it away from optical and electrical parts.')]),

    guide('air-assist-pump-maintenance', 'Air Assist Pump Care & Airflow Checks', 'maintenance',
          'Inspect accessible pump intake, tubing and output without opening electrical housings or assuming a filter can be washed.',
          ['novaFaq', 'l2Safety', 'novaProduct'], [
        s('Identify the pump and its controls', 'Record whether the machine uses NOVA\'s smart air-pump controls or an L2 accessory configuration. The control method and service parts may differ. Also identify whether a suspected filter belongs to the pump, the enclosure exhaust or an external purifier; those are different systems.'),
        s('Inspect with the equipment off', 'Stop processing, switch off and disconnect the relevant power supplies before access.', ['Look for accumulated dust at accessible intake areas.', 'Inspect the external tube for bends, pinching, loose seating or visible residue.', 'Check that the tube route has not been changed by a module or rotary installation.', 'Use the accessory\'s own instructions for removing an intake element or replacing a service part.', 'Do not blow debris deeper into the pump or put liquid into an air line.']),
        s('Use condition and the accessory instructions', 'NOVA\'s FAQ identifies pump operation and blocked or bent tubing as causes to check when marks burn abnormally. It does not establish that every pump has the same replaceable filter or cleaning interval. Match the exact accessory before ordering parts, washing an element or copying another pump\'s service schedule.'),
        s('Check normal airflow before another cut', 'After documented maintenance and correct reconnection, verify the intended control mode and normal airflow without exposing the beam or reaching into moving equipment. If output stays absent, the pump overheats or noise is abnormal, stop and contact support. Do not open a powered pump, replace wiring or compensate for missing air with more laser exposure.'),
    ], related=['troubleshooting/nova-smart-air-assist/', 'troubleshooting/scorch-marks-engraving/', 'troubleshooting/overheating-warning/'],
          faq=[('Should I wash the air-pump filter like the NOVA built-in exhaust filter?', 'Not unless the exact pump instructions permit it. The washable rear machine filter and a pump intake element are not interchangeable maintenance items.')]),

    guide('honeycomb-bed-cleaning', 'Clean the Laser Working Bed & Remove Debris', 'maintenance',
          'Clear scraps and residue from the correct working panel without burning deposits away or damaging an accessory bed.',
          ['l2Safety', 'novaRotary', 'novaInternalFilter'], [
        s('Check which working panel is installed', 'A blade cutting panel, an optional honeycomb panel and the surface below it have different construction. NOVA\'s rotary guide identifies a blade cutting panel and aluminum protective plate, not a universal honeycomb bed. Use the maintenance instructions for the actual installed part.'),
        s('Clear loose debris with power off', 'Stop the job, allow the workpiece and panel to cool, switch off and disconnect power.', ['Remove finished parts and loose offcuts without touching a moving or hot component.', 'Check underneath the working panel for small pieces that could lift stock or interfere with airflow.', 'Use the component\'s documented removal method if access requires taking out a panel.', 'Inspect for damage or residue that affects flatness before reinstalling it.']),
        s('Choose cleaning materials for the panel', 'Remove deposits using the method and cleaning product approved for that panel. Do not flood the machine, soak electrical parts, scrape a coated bed aggressively or assume that a bonded honeycomb insert is washable. Keep solvent vapors and flammable supplies away from processing, and reconnect power only after cleaned components are dry and correctly installed.'),
        s('Check a flat reference after reassembly', 'Make sure the panel is seated properly and no scrap is trapped beneath it. Verify a flat offcut before making a detailed job. L2\'s safety guide identifies accumulated residue and debris as a fire risk, so cleaning should not wait for a visibly scorched bed. Never run the laser over the panel to burn deposits off as a cleaning shortcut.'),
    ], related=['troubleshooting/uneven-cutting-depth/', 'troubleshooting/excessive-smoke-odor/', 'tutorials/laser-safety/'],
          faq=[('Can I clean a dirty bed by running a burn-off pattern?', 'No. That adds heat and fire risk to accumulated residue. Clean the stopped, cooled component using its approved maintenance method.')]),

    guide('laser-module-lifespan', 'When Does a Laser Module Need Replacement?', 'maintenance',
          'Use documented inspection, a retained baseline sample and support diagnosis instead of treating weak output as proof of a fixed lifespan.',
          ['novaLens', 'novaCoolingFan', 'l2Faq', 'settings'], [
        s('Do not diagnose age from one weak job', 'A lighter engraving can result from stock, focus, contamination, software units or a different module mode. Even a frequently used machine needs those causes separated before the source is judged defective. Keep an earlier successful file and sample so the comparison is meaningful.'),
        s('Check the serviceable optical window first', 'NOVA\'s 10W/20W window guide distinguishes removable contamination from damage and persistent marks requiring window replacement. A damaged window is not automatically the same repair as replacing the entire laser module. Use the component specification for the installed module.'),
        s('Compare a controlled baseline', 'When the machine is otherwise safe and fully assembled, use a small known-stock sample.', ['Verify focus, power, speed units, passes and operation against the earlier record.', 'Check the applicable window, cooling and extraction maintenance.', 'Compare the same simple file on matching stock after cleaning and correct reassembly.', 'Stop for abnormal heat, damaged optics, missing output or an unresolved warning instead of increasing exposure indefinitely.']),
        s('Choose the right replacement with support', 'There is no single guaranteed service-hour limit for every module and use pattern in the references linked here. Record the module identity, usage history if known, maintenance performed and baseline results. Confirm compatibility and the actual faulty component before ordering a window or complete module. Ask about current warranty terms separately; a maintenance reminder or a weak sample alone does not decide warranty coverage.'),
    ], related=['troubleshooting/weak-laser-output/', 'troubleshooting/lens-mirror-cleaning/', 'troubleshooting/overheating-warning/'],
          faq=[('Does weak output mean the whole laser module has worn out?', 'Not necessarily. Focus, stock and a contaminated or damaged optical window can affect the result. Compare a documented baseline and the correct maintenance checks before choosing a replacement.')]),

    guide('nova-module-removal-install', 'Remove & Reinstall a NOVA 10W or 20W Module', 'maintenance',
          'Follow NOVA\'s supported removal direction, protect the focus probe and secure the module fully before restoring power.',
          ['novaLens', 'novaFaq', 'novaProduct'], [
        s('Match the instructions to the module', 'This removal sequence follows the illustrated NOVA laser-window guide for the 10W and 20W modules. It is not a general removal method for L2 or proof that the infrared module uses identical service access. Confirm the module identity and use its own instructions before handling it.'),
        s('Prepare a clean, safe work area', 'Stop processing, switch off, disconnect the power supply and allow the module to cool completely. Prepare the supplied tool, a stable clean surface and a place for the screws. Keep the window from touching the table, and never lift the module by the focus probe.'),
        s('Remove and reinstall as illustrated', 'Use the original photographs to identify the locating features and travel direction.', ['Support the module with one hand and remove both securing screws, keeping support under it as the last screw comes free.', 'Keep the module level and slide it out horizontally; stop if resistance remains.', 'If the Focus Module must be removed for maintenance, lift its body straight up without bending the probe.', 'After maintenance, seat the Focus Module correctly and align the laser module with its original mounting features.', 'Reinstall the module steadily, then reinstall and tighten both securing screws.']),
        s('Complete the checks before power-on', 'Confirm that the module is stable, its window and Focus Module are seated, the mounting area is clean and all tools are removed. Close the lid, restore power and check normal detection and focusing using suitable test material. If detection, noise or output is abnormal, stop, disconnect power and recheck the installation; ask support if the fault remains. Do not start a job with a loose or partially seated module.'),
    ], models=['NOVA'], related=['troubleshooting/nova-module-swap-not-recognized/', 'troubleshooting/lens-mirror-cleaning/', 'troubleshooting/nova-autofocus-failed/'],
          faq=[('Can I run a quick test before tightening both screws?', 'No. Complete seating and secure both screws before restoring power or starting processing.')], illustration='nova-window'),

    # Existing routes remain in place; add the model distinctions missing from the first draft.
    existing_notes = {
        'laser-not-firing': ('NOVA startup and L2 alarms', 'On L2, identify the documented alarm instead of assuming every no-output condition is a weak laser. On NOVA, check the closed lid, correctly installed module and bottom-cover alignment using its FAQ. Neither a moving head nor an active camera proves that processing output is enabled.', ['l2Alarm', 'novaFaq']),
        'weak-laser-output': ('Check the optical window before replacing the source', 'For NOVA 10W/20W modules, the window guide gives separate cleaning and replacement criteria. A stained or scratched window is a different component from the complete laser module. Use dedicated lens-cleaning material and the correct power-off removal method; L2 access is not interchangeable.', ['novaLens', 'l2Faq']),
        'not-cutting-through': ('Focus for the model you are using', 'Set L2 focus with its focusing rod against the workpiece and secure the module as described in the L2 FAQ. NOVA uses its own autofocus workflow. If a cut fails only in one area, compare sheet flatness and local thickness before changing power across the whole job.', ['l2Faq', 'novaFaq']),
        'burnt-charred-edges': ('Separate air-assist and exhaust checks', 'The NOVA FAQ names excessive parameters and a pump or tube problem as checks for burn marks. The pump that supplies air is not the enclosure exhaust fan. Inspect tubing and the relevant filter separately, and do not wash an optional purifier cartridge using the built-in machine-filter instructions.', ['novaFaq', 'novaInternalFilter']),
        'engraving-too-light-or-dark': ('Keep scan spacing and exposure separate', 'In image work, scan-line interval affects how adjacent lines overlap. LightBurn\'s Interval Test can compare useful spacing on the actual stock. Keep a small tonal crop and record its image mode, size, interval, speed and power rather than changing all controls together.', ['lightburnImages', 'lightburnInterval']),
        'engraving-misalignment': ('NOVA camera calibration is a separate check', 'For a consistently displaced NOVA overlay, use its Studio camera wizard with one clean, flat kraft-paper sheet. Keep the lid closed during framing, autofocus and pattern engraving, and do not move the paper. A blank that shifts or an axis that loses position needs a different diagnosis.', ['novaCamera']),
        'wavy-blurry-engraving': ('Compare camera clarity with the engraved result', 'A blurred NOVA camera image may need top-cover camera cleaning and calibration; a sharp overlay with wavy vectors points elsewhere. Do not change the physical camera mounting to conceal a motion problem. Keep a vector sample and a small filled sample for comparison.', ['novaLidCamera', 'lightburnImages']),
        'machine-wont-turn-on': ('Separate no power from failed initialization', 'NOVA\'s FAQ startup checks cover lid, module and bottom-cover installation. Those checks apply when initialization fails; they do not justify opening a power supply on a machine showing no normal power indication. Report the actual startup stage and whether the screen or lights ever appeared.', ['novaFaq', 'l2Safety']),
        'homing-failure': ('Do not move the limit switch to silence the symptom', 'L2\'s alarm reference identifies a triggered limit switch. A material or fixture obstruction and a changed coordinate setup should be checked before mechanical adjustment. NOVA and L2 have different assemblies, so an unresolved homing fault needs the exact model and motion direction in the support report.', ['l2Alarm', 'novaFaq']),
        'usb-not-connecting': ('Use the documented serial-port selection', 'TOOCAA\'s L2 connection guide uses Chrome and the device\'s actual serial port; disconnecting and reconnecting the USB cable identifies the newly appearing port. NOVA also has a supported USB workflow. L2\'s FAQ names the CH340 driver when a driver is required; do not install unrelated driver bundles.', ['l2Connection', 'novaConnection', 'l2Faq']),
        'wifi-connection-troubleshooting': ('NOVA Wi-Fi prerequisites', 'Use NOVA and the computer on the same Wi-Fi network and IP subnet, avoid captive-portal networks, and confirm the connection on NOVA. The current NOVA connection guide also describes the TOOCAA Connect browser extension for its Wi-Fi workflow; obtain it through that official guide or its store link, not an unrelated download. The FAQ specifies 2.4 GHz for a mobile-hotspot test.', ['novaConnection', 'novaFaq']),
        'lightburn-not-detecting': ('Use the profile for the actual machine', 'The L2 FAQ calls for normal power, a stable data cable, the correct controller/connection selection and no competing control session. NOVA has its own connection and camera instructions; a working L2 profile is not proof that NOVA should use the same device setup.', ['l2Faq', 'novaConnection']),
        'rotary-attachment-issues': ('The two rotary systems are different', 'L2\'s 5-in-1 rotary guide does not replace the NOVA rotary instructions. NOVA uses the 90-degree X-axis setup, its own connections and the workpiece diameter at the actual processing area. Confirm the accessory and module before transferring any configuration between machines.', ['rotary', 'novaRotary']),
        'excessive-smoke-odor': ('Know which filter you are servicing', 'NOVA\'s rear built-in machine filter has a documented removal, clean-water rinsing and complete-drying procedure. An optional external purifier has its own cartridge instructions. Reduced airflow after correct reassembly still requires stopping and investigation, not assuming the room air is safe.', ['novaInternalFilter', 'novaPurifierFilter']),
        'firmware-update-stuck': ('NOVA has a documented on-device update route', 'The NOVA FAQ describes checking available system-drive space for failed Studio updates and using the touchscreen update notification when appropriate. The offered version is device-specific. Do not interrupt an active update or use an L2 recovery file for NOVA.', ['novaFaq', 'l2Faq']),
        'safety-alarm': ('Use the right warning reference', 'L2 has published alarm descriptions. NOVA\'s touchscreen message and model documentation should guide its diagnosis. A factory reset, sensor bypass or repeated start attempt is not a substitute for resolving the condition that triggered an alarm.', ['l2Alarm', 'novaFaq']),
    }
    next_checks = {
        'laser-not-firing': [('Layer output is disabled', 'Correct the layer output and operation in Studio before another properly framed test.'), ('A cover or module warning remains', 'Keep processing stopped and use the exact model warning reference.'), ('No output with a ready machine and a known file', 'Send the configuration and error/status record to support; do not expose the beam for diagnosis.')],
        'weak-laser-output': [('Only new stock produces weak marks', 'Compare the material identity, finish and batch against the retained sample.'), ('The window has persistent damage or deposits', 'Use the module-specific optical-window inspection/replacement guidance.'), ('The earlier baseline still fails after correct maintenance', 'Record the matched settings and request module diagnosis.')],
        'not-cutting-through': [('The software only traces a surface line', 'Check that the intended cutting operation, not a scoring/engraving mode, is selected.'), ('Failure follows a patch in the wood', 'Inspect thickness, glue pockets and material variation.'), ('Failure follows one bed location', 'Use the uneven-cut-depth guide rather than repeatedly burning the same spot.')],
        'burnt-charred-edges': [('A broad surface haze surrounds the cut', 'Check smoke deposits and extraction separately from kerf depth.'), ('The same outline is cut twice unexpectedly', 'Remove duplicated geometry or unintended layer output.'), ('Burn marks are strongly directional', 'Check the documented air-pump and tubing operation before another cut.')],
        'engraving-too-light-or-dark': [('The exported preview already lacks detail', 'Return to photo preparation instead of compensating with laser power.'), ('Visible regular scan gaps remain', 'Test scan spacing using the image/interval guidance.'), ('One stock batch differs from another', 'Retest the actual surface and keep the same file and dimensions.')],
        'engraving-misalignment': [('The camera overlay has a constant offset', 'Use the model-specific camera calibration guide.'), ('Each pass drifts farther', 'Investigate lost position or moving workholding.'), ('Only a reimported file is displaced', 'Check its physical dimensions, origin and coordinate mode.')],
        'wavy-blurry-engraving': [('Only the on-screen NOVA camera picture is blurred', 'Use top-cover camera inspection and cleaning, not motion calibration.'), ('The source image is blurred', 'Prepare a sharper original at the intended size.'), ('A simple vector becomes wavy on the workpiece', 'Stop for an unresolved motion or workholding problem.')],
        'machine-wont-turn-on': [('No normal power indication appears', 'Check the approved external supply and visible cable seating; do not open the power supply.'), ('NOVA powers on but initialization fails', 'Check normal lid, module and bottom-cover installation using the FAQ.'), ('Startup repeatedly fails after normal checks', 'Preserve the displayed sequence and request service.')],
        'homing-failure': [('Stock or a fixture blocks travel', 'Power down before clearing it and recheck the complete clearance.'), ('A wrong profile sends the frame beyond the workspace', 'Correct the model/work area and origin before another job.'), ('The axis repeatedly collides or stalls', 'Do not move the switch by guesswork; contact support with the movement direction.')],
        'usb-not-connecting': [('No device port appears', 'Check the data cable, browser permission and model-specific driver requirement.'), ('The port appears but another app holds it', 'Close the other control session, then select the actual machine port.'), ('L2 disconnects after an interval on Windows', 'Review the USB selective-suspend checks in the L2 FAQ.')],
        'wifi-connection-troubleshooting': [('NOVA joined Wi-Fi but Studio cannot reach it', 'Check subnet, current IP, TOOCAA Connect and device confirmation.'), ('The network needs a captive portal', 'Use a network type supported by the official connection guide.'), ('A hotspot is used for comparison', 'Follow the FAQ\'s 2.4 GHz hotspot requirement; do not expose controls to the internet.')],
        'lightburn-not-detecting': [('No usable serial port is visible', 'Resolve the USB/data-cable/driver problem first.'), ('A different app has the machine connection', 'Close that session before connecting from LightBurn.'), ('The controller/profile is uncertain', 'Use the actual model\'s official device instructions rather than guessing a controller.')],
        'rotary-attachment-issues': [('The accessory is not detected', 'Check its exact model, power-off connection procedure and supported device configuration.'), ('The mark wraps to the wrong width', 'Check the measured diameter at the engraving area, grip and configuration.'), ('The setup is NOVA rather than L2', 'Use NOVA\'s 90-degree X-axis rotary guide instead of the L2 installation.')],
        'excessive-smoke-odor': [('Smoke escapes around the enclosure', 'Stop processing and inspect the complete documented exhaust route.'), ('The NOVA rear filter is dirty', 'Use its removal, separate cleaning and complete-drying procedure.'), ('An optional purifier is fitted', 'Check its own filter/cartridge instructions; do not apply the rear-filter washing method.')],
        'firmware-update-stuck': [('A Studio download or preparation fails', 'Check the computer environment, available space and exact error first.'), ('An update is already running on the device', 'Do not use a generic timed power-cycle; follow the current recovery guidance.'), ('The offered model or firmware file is uncertain', 'Stop before applying it and confirm the correct device-specific release.')],
        'safety-alarm': [('A hazard or damaged safeguard remains', 'Leave the machine out of processing service.'), ('Only an L2 beep reference is available', 'Do not use it as a decoder for NOVA.'), ('The same warning returns after normal checks', 'Request support with the full message and operating stage rather than bypassing it.')],
    }
    for item in pages:
        if item['group'] != 'Troubleshooting':
            continue
        slug = item['path'].rstrip('/').split('/')[-1]
        if slug not in existing_notes:
            continue
        heading, text, sources = existing_notes[slug]
        item['sections'].insert(1, section(heading, text))
        for block in item['sections']:
            if block.get('anchor') == 'checks':
                block['ordered'] = True
        item['sources'] = list(dict.fromkeys([*sources, *item['sources']]))
        item['models'] = ['NOVA'] if slug == 'wifi-connection-troubleshooting' else ['L2', 'NOVA']
        result = section('What the check tells you', 'Choose the next step from the observed result, keeping a record of what actually changed.')
        result['table'] = dict(headers=['Observed result', 'Next step'], rows=next_checks[slug])
        item['sections'].insert(-1, result)

    scope_notes = {
        'weak-laser-output': 'User checks do not include exposed-beam power measurement; optical-output diagnosis belongs with authorized service.',
        'uneven-cutting-depth': 'Covers stock flatness, support and model-specific focus; no undocumented bed-leveling or focus-ramp adjustment is prescribed.',
        'kerf-too-wide': 'Fit compensation is based on measured coupons, not an invented universal kerf table or unapproved replacement lens.',
        'engraving-misalignment': 'No generic pulley-screw, belt-tension or motion-calibration values are transferred between models.',
        'machine-wont-turn-on': 'No internal PSU/fuse repair or unsupported model-specific emergency-stop mechanism is prescribed.',
        'homing-failure': 'No undocumented wiring changes, homing-direction edits or limit-switch relocation is prescribed.',
        'motor-skipping-grinding': 'No published model-specific driver-current or acceleration values were established; the guide excludes guessed service adjustments.',
        'axis-drift-calibration': 'No unsupported steps-per-mm, backlash or controller-save values are supplied.',
        'frame-squareness-alignment': 'Geometry measurement is covered; structural re-alignment requires the exact hardware service procedure.',
        'nova-rotary-90-degree': 'Uses the NOVA rotary procedure, not L2 steps-per-rotation or a generic firmware mode.',
        'file-transfer-failed': 'Storage media and accepted formats are model-specific; no universal FAT format or filename limit is invented.',
        'firmware-update-stuck': 'No unverified bootloader, manual-flash or brick-recovery sequence is supplied.',
        'toocaa-app-crashes': 'Current Studio is browser-based; the guide does not invent desktop/iOS reinstall steps.',
        'nova-firmware-ota': 'Documents the official touchscreen update route; no unverified USB firmware-recovery fallback is claimed.',
        'nova-autofocus-failed': 'Focus checks follow the NOVA FAQ and probe-maintenance source; no generic sensor bypass or height-offset value is supplied.',
        'nova-touchscreen-issues': 'No undocumented static-discharge repair, calibration menu or firmware-reflash sequence is supplied.',
        'nova-ai-material-recognition': 'Recognition is tied to documented cards/tags, not chemical identification or an invented AI database-sync control.',
        'nova-smart-air-assist': 'Pump/tube checks are documented; no unverified auto-calibration or hidden override menu is claimed.',
        'nova-breathing-light-status': 'The proposed green/blue/red NOVA decoder is unverified and is not published as fact; use the touchscreen and official support.',
        'nova-child-lock-forgot-password': 'No universal master PIN or verified child-lock bypass is published in the reviewed FAQ; use authorized recovery.',
        'nova-camera-preview-lag': 'No unverified camera-resolution or GPU-acceleration control is claimed.',
        'nova-smart-settings-reset': 'Factory reset and a full restart are documented; an automatic calibration backup/restore feature is not established.',
        'flame-detection-false-alarm': 'No safety-sensor bypass or undocumented sensitivity reduction is prescribed.',
        'protective-cover-sensor': 'No magnet bypass, sensor wiring change or generic hinge adjustment is prescribed.',
        'emergency-stop-reset': 'Reset controls differ by model; no unsupported universal twist/button sequence is supplied.',
        'overheating-warning': 'No arbitrary ambient-temperature threshold or duty-cycle limit is invented.',
        'nova-exhaust-filter-replacement': 'Built-in filter rinsing/drying is documented; no unverified part number or fixed replacement life is supplied.',
        'lens-mirror-cleaning': 'NOVA 10W/20W procedure uses official photographs; a universal 99% IPA rule is not imposed on all optical coatings.',
        'belt-tension-adjustment': 'Inspection and escalation are covered; the source does not supply a universal tension frequency or screw-turn count.',
        'rail-lubrication-guide': 'NOVA rod cleaning and specified grease are documented; no unsupported retail product or fixed interval is invented.',
        'air-assist-pump-maintenance': 'Pump intake elements are not treated as the separately washable NOVA exhaust filter.',
        'honeycomb-bed-cleaning': 'Cleaning is matched to the installed panel; no universal degreaser, compressed-air or replacement schedule is invented.',
        'laser-module-lifespan': 'No guaranteed operating-hour life or DIY optical-output measurement is claimed.',
        'nova-module-removal-install': 'Removal photographs and sequence apply to NOVA 10W/20W; the same disassembly is not asserted for the IR module.',
    }
    for item in pages:
        if item['group'] == 'Troubleshooting':
            item['scope_note'] = scope_notes.get(item['path'].rstrip('/').split('/')[-1], '')
